const incidentKey='amrita-incidents-v1';
let incidents;try{incidents=JSON.parse(localStorage.getItem(incidentKey))||[]}catch{incidents=[]}
function incidentSave(){localStorage.setItem(incidentKey,JSON.stringify(incidents));if(window.SharedState)SharedState.enqueue()}
function incidentAudit(item,action,note){const time=new Date().toISOString();item.timeline.push({action,note,time,actor:location.hash==='#warden'?'Warden (demo)':location.hash==='#security'?'Gate security (demo)':'Security head (demo)'});const v=visits.find(v=>v.id===item.visit);if(item.source==='browser'&&v)audit(action,v,{actor:item.timeline.at(-1).actor,incident:item.id,note});else incidentSave()}
function reportIncident(visitId,flag=null){const data=headData(),v=data.visits.find(v=>v.id===visitId);if(!v)return;if(flag&&incidents.some(i=>i.source===headSource&&i.flag===flag.id&&i.status!=='resolved')){headTab='incidents';securityHead();toast('This flag already has an unresolved incident.');return}const dialog=document.querySelector('#head-dialog');document.querySelector('#head-dialog-content').innerHTML=`<h2>Report a security concern</h2><p>${esc(v.plate)} · ${esc(v.id)}<br>${flag?esc(flag.detail):'Describe the observed concern. A report starts a human investigation.'}</p><form id="incident-report"><label class="field">Concern<input name="title" required maxlength="120" value="${esc(flag?.title||'')}"></label><label class="field">Assign to<select name="owner"><option value="security">Gate security</option><option value="warden">Assigned warden</option></select></label><label class="field">Priority<select name="priority"><option>Normal</option><option>High</option></select></label><label class="field">Required follow-up<textarea name="note" required maxlength="500" placeholder="Explain what staff should verify"></textarea></label><p class="hint">Appears in the assigned team's dashboard. No automatic blacklisting, permission cancellation or gate operation.</p><button class="btn">Report to team</button></form>`;dialog.showModal();document.querySelector('#incident-report').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));const item={...values,id:'INC-'+crypto.randomUUID().slice(0,8).toUpperCase(),source:headSource,visit:v.id,plate:v.plate,warden:v.warden,flag:flag?.id||null,status:'open',created:new Date().toISOString(),timeline:[]};incidents.unshift(item);if(flag){headSettings.reviews[headSource+':'+flag.id]={note:'Reported as '+item.id,time:item.created};headSave()}incidentAudit(item,'Incident reported',values.note);incidentSave();dialog.close();securityHead();toast('Incident assigned. The team can acknowledge, investigate and resolve it.')};}
function incidentPanel(role){const rows=incidents.filter(i=>role==='head'?i.source===headSource:i.owner===role);return `<section class="panel head-space"><div class="head-title"><h2>${role==='head'?'Incident tracking':'Security head follow-up inbox'}</h2><span class="head-tag">${rows.filter(i=>i.status!=='resolved').length} unresolved</span></div><p class="hint">Report → acknowledge and investigate → record outcome → resolve. A flag alone does not change entry or exit permission.</p>${rows.map(i=>`<article class="head-alert"><div><small>${esc(i.id)} · ${esc(i.plate)} · ${esc(i.source==='sample'?'SAMPLE incident':i.visit)}</small><strong>${esc(i.title)}</strong><p>${esc(i.priority)} priority · Assigned to ${i.owner==='warden'?esc(i.warden):'gate security'} · ${esc(i.status.replace('_',' '))}</p><details><summary>Incident history</summary>${i.timeline.map(t=>`<p>${stamp(t.time)} · ${esc(t.actor)}<br><b>${esc(t.action)}</b> · ${esc(t.note)}</p>`).join('')}</details></div><div>${i.status!=='resolved'?`<button class="btn secondary table-btn" data-incident-action="${esc(i.id)}">${i.status==='open'?'Acknowledge / investigate':'Record outcome'}</button>`:'<span class="head-tag">Resolved</span>'}</div></article>`).join('')||'<p class="hint">No incidents assigned.</p>'}<dialog id="incident-dialog"><button class="btn secondary" id="incident-close">Close</button><div id="incident-content"></div></dialog></section>`}
function bindIncidents(role){const dialog=document.querySelector('#incident-dialog');if(!dialog)return;document.querySelector('#incident-close').onclick=()=>dialog.close();document.querySelectorAll('[data-incident-action]').forEach(b=>b.onclick=()=>{const i=incidents.find(x=>x.id===b.dataset.incidentAction);document.querySelector('#incident-content').innerHTML=`<h2>${esc(i.title)}</h2><form id="incident-update"><label class="field">Action<select name="action">${i.status==='open'?'<option value="investigate">Acknowledge and investigate</option>':''}<option value="resolve">Resolve with outcome</option></select></label><label class="field">Outcome<select name="outcome"><option>Further verification requested</option><option>No issue found / false positive</option><option>Concern verified; follow-up recorded</option></select></label><label class="field">Investigation note<textarea name="note" required maxlength="500"></textarea></label><p class="hint">Use the normal warden approval and guard verification workflow for any passage decision.</p><button class="btn">Save action</button></form>`;dialog.showModal();document.querySelector('#incident-update').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));i.status=values.action==='resolve'?'resolved':'in_progress';i.outcome=values.outcome;incidentAudit(i,i.status==='resolved'?'Incident resolved':'Incident acknowledged',values.outcome+': '+values.note);incidentSave();dialog.close();if(role==='head')securityHead();else if(role==='warden')warden();else security();toast('Incident action saved to shared history.')};})}
